-- Life Buddy - Demonstration seed data (Phase 2)
-- Database: lifebuddy_db
-- IMPORTANT: All records below are CLEARLY LABELLED DEMONSTRATION DATA. No real personal or medical information.
-- Safe to run repeatedly: uses fixed IDs and ON DUPLICATE KEY UPDATE for idempotency.
-- Execution against a live MySQL server has NOT been verified in this environment.

USE lifebuddy_db;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Users (demo): 1 caregiver, 2 assisted users
-- Password/PIN hashes below are PLACEHOLDER bcrypt-like strings for demo structure only.
-- Real hashes must be generated by the backend (bcrypt) during Phase 3+; replace before production/demo login tests.
ON DUPLICATE KEY UPDATE
  role=VALUES(role), email=VALUES(email), full_name=VALUES(full_name), display_name=VALUES(display_name),
  status=VALUES(status), preferred_language=VALUES(preferred_language), phone_number=VALUES(phone_number), updated_at=CURRENT_TIMESTAMP;

-- Caregiver links (demo): caregiver 1 linked to users 2 and 3
ON DUPLICATE KEY UPDATE relationship_type=VALUES(relationship_type), link_status=VALUES(link_status), linked_by=VALUES(linked_by), updated_at=CURRENT_TIMESTAMP;

-- User preferences (demo)
ON DUPLICATE KEY UPDATE language=VALUES(language), text_size=VALUES(text_size), contrast_mode=VALUES(contrast_mode),
  speech_rate=VALUES(speech_rate), voice_enabled=VALUES(voice_enabled), reduced_motion=VALUES(reduced_motion),
  notifications_enabled=VALUES(notifications_enabled), updated_at=CURRENT_TIMESTAMP;

-- Communication items (demo/global tiles)
ON DUPLICATE KEY UPDATE category=VALUES(category), label_en=VALUES(label_en), label_bn=VALUES(label_bn),
  icon_key=VALUES(icon_key), speak_text_en=VALUES(speak_text_en), speak_text_bn=VALUES(speak_text_bn),
  sentence_role=VALUES(sentence_role), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=CURRENT_TIMESTAMP;

-- Favourite phrases (demo for user 2)
ON DUPLICATE KEY UPDATE selected_item_keys=VALUES(selected_item_keys), phrase_en=VALUES(phrase_en), phrase_bn=VALUES(phrase_bn),
  phrase_label=VALUES(phrase_label), is_active=VALUES(is_active), updated_at=CURRENT_TIMESTAMP;

-- Routine and steps (demo for user 2)
ON DUPLICATE KEY UPDATE title_en=VALUES(title_en), title_bn=VALUES(title_bn), description_en=VALUES(description_en),
  description_bn=VALUES(description_bn), icon_key=VALUES(icon_key), is_active=VALUES(is_active), updated_at=CURRENT_TIMESTAMP;

ON DUPLICATE KEY UPDATE instruction_en=VALUES(instruction_en), instruction_bn=VALUES(instruction_bn),
  image_key=VALUES(image_key), audio_hint_key=VALUES(audio_hint_key), updated_at=CURRENT_TIMESTAMP;

-- Routine completion sample (demo)
ON DUPLICATE KEY UPDATE completion_status=VALUES(completion_status), completed_at=VALUES(completed_at),
  synced_at=VALUES(synced_at), source=VALUES(source), notes=VALUES(notes), updated_at=CURRENT_TIMESTAMP;

-- Medicines and reminders (demo, caregiver-entered; no real medical advice)
ON DUPLICATE KEY UPDATE medicine_name=VALUES(medicine_name), prescribed_instructions=VALUES(prescribed_instructions),
  notes=VALUES(notes), start_date=VALUES(start_date), end_date=VALUES(end_date), is_active=VALUES(is_active), updated_at=CURRENT_TIMESTAMP;

ON DUPLICATE KEY UPDATE reminder_time=VALUES(reminder_time), frequency=VALUES(frequency), days_of_week=VALUES(days_of_week),
  reminder_label=VALUES(reminder_label), is_active=VALUES(is_active), updated_at=CURRENT_TIMESTAMP;

ON DUPLICATE KEY UPDATE scheduled_for=VALUES(scheduled_for), status=VALUES(status), responded_at=VALUES(responded_at),
  notes=VALUES(notes), updated_at=CURRENT_TIMESTAMP;

-- Emergency contacts (demo)
ON DUPLICATE KEY UPDATE contact_name=VALUES(contact_name), relationship_label=VALUES(relationship_label),
  phone_number=VALUES(phone_number), email=VALUES(email), is_primary=VALUES(is_primary), updated_at=CURRENT_TIMESTAMP;

-- SOS alert (demo, dashboard notification baseline)
ON DUPLICATE KEY UPDATE latitude=VALUES(latitude), longitude=VALUES(longitude), location_status=VALUES(location_status),
  alert_status=VALUES(alert_status), delivery_status=VALUES(delivery_status), delivery_channel=VALUES(delivery_channel),
  delivery_message=VALUES(delivery_message), failure_reason=VALUES(failure_reason), triggered_at=VALUES(triggered_at),
  acknowledged_at=VALUES(acknowledged_at), acknowledged_by=VALUES(acknowledged_by), updated_at=CURRENT_TIMESTAMP;

-- Situation steps (predefined demo/global, bilingual)
ON DUPLICATE KEY UPDATE title_en=VALUES(title_en), title_bn=VALUES(title_bn), instruction_en=VALUES(instruction_en),
  instruction_bn=VALUES(instruction_bn), image_key=VALUES(image_key), is_predefined=VALUES(is_predefined),
  is_active=VALUES(is_active), updated_at=CURRENT_TIMESTAMP;

-- Activity logs (demo)
ON DUPLICATE KEY UPDATE event_type=VALUES(event_type), entity_type=VALUES(entity_type), entity_id=VALUES(entity_id),
  summary=VALUES(summary), metadata_json=VALUES(metadata_json);

SET FOREIGN_KEY_CHECKS = 1;

-- Reset auto-increment pointers (optional, for demo predictability)
ALTER TABLE users AUTO_INCREMENT = 100;
ALTER TABLE caregiver_links AUTO_INCREMENT = 100;
ALTER TABLE user_preferences AUTO_INCREMENT = 100;
ALTER TABLE routines AUTO_INCREMENT = 100;
ALTER TABLE routine_steps AUTO_INCREMENT = 100;
ALTER TABLE routine_completions AUTO_INCREMENT = 100;
ALTER TABLE medicines AUTO_INCREMENT = 100;
ALTER TABLE medicine_reminders AUTO_INCREMENT = 100;
ALTER TABLE medicine_logs AUTO_INCREMENT = 100;
ALTER TABLE emergency_contacts AUTO_INCREMENT = 100;
ALTER TABLE sos_alerts AUTO_INCREMENT = 100;
ALTER TABLE communication_items AUTO_INCREMENT = 100;
ALTER TABLE favourite_phrases AUTO_INCREMENT = 100;
ALTER TABLE situation_steps AUTO_INCREMENT = 100;
ALTER TABLE device_tokens AUTO_INCREMENT = 100;
ALTER TABLE activity_logs AUTO_INCREMENT = 100;

-- End of demo seed
